// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        // Deploy a helper that always succeeds when called with transferFrom signature
        address helper = address(new Succeeder());
        // Use try/catch to observe success and capture the return value
        try c.transfer(from, helper, _tos, v) returns (bool ret) {
            assertTrue(ret == true);
        } catch {
            // If the call reverts (e.g., due to insufficient allowance in the helper),
            // the property vacuously holds for this input because we only care about non-reverting cases.
        }
    }
}

contract Succeeder {
    // Any call with the transferFrom signature returns true to simulate a successful transfer
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
    // Ghost fallback to handle any other calls gracefully without reverting
    fallback() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address from, address token, address[] memory tos, uint v) public {
        require(tos.length > 1);
        bool ret = c.transfer(from, token, tos, v);
        assert(ret);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 1 && from != caddress);
        bool reverted; try c.transfer(from, caddress, _tos, v) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 1 && from != caddress && v == 0);
        bool reverted; try c.transfer(from, caddress, _tos, v) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 1 && from != caddress && v == 0 && _tos[0] != address(0));
        bool reverted; try c.transfer(from, caddress, _tos, v) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable {}
